adcs_status_t st;
if ((b == NULL) || (r == NULL) || (w == NULL) || (out == NULL)) {
    *out = (adcs_quat_t){1, 0, 0, 0};
    return ADCS_E_NULL;
}
if ((n < 2U) || (n > 32U)) {
    *out = (adcs_quat_t){1, 0, 0, 0};
    return ADCS_E_RANGE;
}
st = adcs_quest(b, r, w, n, out);
if (st != ADCS_OK) {
    *out = (adcs_quat_t){1, 0, 0, 0};
    return st;
}
return ADCS_OK;
